import itertools

n = 21
fixed_seq = {5: -1, 12: -1, 17: 1, 20: 1}
free_positions = [i for i in range(n) if i not in fixed_seq]

# Let's check what C_1 and C_8 values are possible with the fixed seq values
c1_values = {}
c8_values = {}

for bits in itertools.product([-1, 1], repeat=len(free_positions)):
    seq = [0]*n
    for i in range(n):
        if i in fixed_seq:
            seq[i] = fixed_seq[i]
        else:
            seq[i] = bits[free_positions.index(i)]

    C = []
    for k in range(n):
        s = 0
        for i in range(n - k):
            s += seq[i] * seq[i + k]
        C.append(s)

    c1 = C[1]
    c8 = C[8]

    if c1 not in c1_values:
        c1_values[c1] = 0
    c1_values[c1] += 1

    if c8 not in c8_values:
        c8_values[c8] = 0
    c8_values[c8] += 1

print("C_1 values and their frequencies:")
for v in sorted(c1_values.keys()):
    print(f"  C_1 = {v}: {c1_values[v]} times")

print("\nC_8 values and their frequencies:")
for v in sorted(c8_values.keys()):
    print(f"  C_8 = {v}: {c8_values[v]} times")

# So C_1 can only be even numbers (0, ±2) and C_8 can only be odd numbers (±1, ±3)
# This means C_1=-1 and C_8=2 are impossible simultaneously.

# Let me also check C_19
c19_values = {}
for bits in itertools.product([-1, 1], repeat=len(free_positions)):
    seq = [0]*n
    for i in range(n):
        if i in fixed_seq:
            seq[i] = fixed_seq[i]
        else:
            seq[i] = bits[free_positions.index(i)]

    C = []
    for k in range(n):
        s = 0
        for i in range(n - k):
            s += seq[i] * seq[i + k]
        C.append(s)

    c19 = C[19]
    if c19 not in c19_values:
        c19_values[c19] = 0
    c19_values[c19] += 1

print("\nC_19 values and their frequencies:")
for v in sorted(c19_values.keys()):
    print(f"  C_19 = {v}: {c19_values[v]} times")

# C_19 = seq[0]*seq[19] + seq[1]*seq[20]
# With seq[20]=1 fixed, C_19 = seq[0]*seq[19] + seq[1]*1 = seq[0]*seq[19] + seq[1]
# So C_19 can be -2, 0, or 2 (since each term is ±1)
print("\nC_19 = seq[0]*seq[19] + seq[1]*seq[20] = seq[0]*seq[19] + seq[1]")
print("Since seq[20]=1, C_19 = seq[0]*seq[19] + seq[1]")
print("seq[0]*seq[19] is ±1, seq[1] is ±1")
print("So C_19 can be: -2, 0, or 2")
